import Foundation
import Matter

func mtrRequire(_ condition: Bool, _ message: String) {
    if !condition {
        fputs("Matter test failed: \(message)\n", stderr)
        exit(1)
    }
}

func mtrExpectInvalidState(_ err: (any Error)?) {
    mtrRequire((err as? MTRError)?.code == .invalidState, "expected MTRError.invalidState")
}

func mtrCheck<T: RawRepresentable & Equatable>(_ value: T, _ raw: T.RawValue, _ name: String)
where T.RawValue: Equatable {
    mtrRequire(value.rawValue == raw, name)
    mtrRequire(T(rawValue: raw) == value, name + " round-trip")
}

func n(_ v: Int) -> NSNumber { NSNumber(value: v) }
func n(_ v: UInt32) -> NSNumber { NSNumber(value: v) }
func n(_ v: UInt16) -> NSNumber { NSNumber(value: v) }

