func testEnumHashable() {
    mtrRequire(MTRLogType.error.hashValue == MTRLogType.error.hashValue, "log hash")
    mtrRequire(MTRLogType.error != MTRLogType.progress, "log ne")
    mtrRequire(MTRCommissioningFlow.standard != MTRCommissioningFlow.custom, "flow")
    mtrRequire(MTRDeviceState.unknown.rawValue == 0, "state unk")
    mtrRequire(MTRDeviceState.reachable.rawValue == 1, "state reach")
    mtrRequire(MTRDeviceState.unreachable.rawValue == 2, "state unreach")
    mtrRequire(MTRTransportType.UDP.rawValue == 1, "udp")
    mtrRequire(MTRClusterIDType.identifyID != MTRClusterIDType.onOffID, "cluster ids")
    _ = MTRAttributeIDType.globalAttributeClusterRevisionID.hashValue
    _ = MTRCommandIDType.clusterOnOffCommandOnID.hashValue
}

